"""
Voice conversation about a decision card, in the browser (OpenAI gpt-realtime over WebRTC).

The browser asks this route for a short-lived OpenAI client secret; the API key never leaves the
server. The secret carries the session: the card as instructions, a voice, noise handling and the
`record_decision` function. The browser then talks to OpenAI directly and records the decision
through the dashboard's normal card action endpoint.
"""

import json
import os

import httpx
from fastapi import APIRouter, HTTPException

from ask_soony.config import load_dotenv

router = APIRouter()

DECISION_TOOL = {
    "type": "function",
    "name": "record_decision",
    "description": "Record the person's decision on this card as soon as they have decided.",
    "parameters": {
        "type": "object",
        "properties": {
            "decision": {"type": "string", "enum": ["approve", "escalate", "reject"]},
            "note": {"type": "string", "description": "Short reason or condition, if any"},
        },
        "required": ["decision"],
    },
}


def _text(value) -> str:
    if isinstance(value, str):
        return value
    if isinstance(value, dict):
        return "; ".join(f"{k}: {v}" for k, v in value.items() if v not in (None, "", []))
    return json.dumps(value, ensure_ascii=False)


def instructions(card: dict) -> str:
    options = "\n".join(f"- {_text(o)}" for o in card.get("options") or []) or "- none listed"
    facts = [
        f"Title: {card.get('title', '')}",
        f"Edition: {card.get('edition', '')}, part: {card.get('part', '')}",
        f"Copies at risk: {card.get('at_risk')} (if we act: {card.get('at_risk_if_acted')})",
        f"Act by: {card.get('act_by') or 'not given'}; runs dry: {card.get('runs_dry') or 'not given'}",
        f"System says: {card.get('system_says', '')}",
        f"Documents say: {card.get('paper_says', '')}",
        f"Options:\n{options}",
    ]
    return (
        "You are the procurement assistant of the dashboard, talking to a buyer about one decision "
        "card that threatens the product launch. Speak English, calmly and briefly.\n\n"
        + "\n".join(facts)
        + "\n\nStart by stating the problem in two short sentences and the recommended option. "
        "Answer questions only with the facts above; if you do not know, say so. Then ask for a "
        "decision: approve the recommended action, escalate to the next person, or reject. When they "
        "decide, call record_decision, confirm in one sentence and say goodbye.\n\n"
        "The person may be in a noisy room. Only respond to what they say to you about this card. "
        "Ignore background conversations, other languages and fragments; if unsure, ask: 'Sorry, "
        "was that for me?' Never record a decision from background speech."
    )


@router.post("/api/cards/{card_id}/voice")
def voice_session(card_id: str):
    load_dotenv()
    key = os.environ.get("OPENAI_API_KEY")
    if not key:
        raise HTTPException(503, "OPENAI_API_KEY is not set")
    from ask_soony import api  # late import: api includes this router

    card = next((c for c in api.get_state()["cards"] if c.get("id") == card_id), None)
    if card is None:
        raise HTTPException(404, "card not found")
    model = os.environ.get("OPENAI_REALTIME_MODEL", "gpt-realtime-2.1")
    session = {
        "type": "realtime",
        "model": model,
        "instructions": instructions(card),
        "audio": {
            "output": {"voice": os.environ.get("OPENAI_REALTIME_VOICE", "marin")},
            "input": {
                "noise_reduction": {"type": "near_field"},
                "transcription": {"model": "gpt-4o-mini-transcribe"},
                "turn_detection": {
                    "type": "server_vad",
                    "threshold": float(os.environ.get("OPENAI_VAD_THRESHOLD", "0.8")),
                    "prefix_padding_ms": 300,
                    "silence_duration_ms": 700,
                    "create_response": True,
                    "interrupt_response": False,
                },
            },
        },
        "tools": [DECISION_TOOL],
        "tool_choice": "auto",
    }
    resp = httpx.post(
        "https://api.openai.com/v1/realtime/client_secrets",
        headers={"Authorization": f"Bearer {key}"},
        json={"expires_after": {"anchor": "created_at", "seconds": 600}, "session": session},
        timeout=20,
    )
    if resp.status_code >= 300:
        raise HTTPException(502, f"OpenAI refused the session: {resp.text[:300]}")
    return {"client_secret": resp.json().get("value"), "model": model}

import { useRef, useState } from "react";
import type { ActionKind, Card } from "./types";

// Voice conversation about one card with OpenAI gpt-realtime over WebRTC. The server mints a
// short-lived client secret; the decision goes through the normal card action endpoint.

type Line = { who: "assistant" | "you" | "system"; text: string };

const DECISION_TO_ACTION: Record<string, ActionKind> = {
  approve: "allow_once",
  reject: "dismiss",
  escalate: "edit",
};

export default function VoiceCall({
  card,
  onAction,
  autoStart = false,
}: {
  card: Card;
  onAction: (id: string, action: ActionKind, note?: string) => void;
  autoStart?: boolean;
}) {
  const [status, setStatus] = useState<"idle" | "connecting" | "live" | "ended" | "error">("idle");
  const [lines, setLines] = useState<Line[]>([]);
  const pc = useRef<RTCPeerConnection | null>(null);
  const started = useRef(false);
  const add = (l: Line) => setLines((prev) => [...prev, l].slice(-12));

  function hangUp() {
    pc.current?.getSenders().forEach((s) => s.track?.stop());
    pc.current?.close();
    pc.current = null;
    setStatus("ended");
  }

  async function start() {
    if (started.current && status !== "ended" && status !== "error") return;
    started.current = true;
    setStatus("connecting");
    setLines([]);
    try {
      const res = await fetch(`/api/cards/${encodeURIComponent(card.id)}/voice`, { method: "POST" });
      if (!res.ok) throw new Error(await res.text());
      const { client_secret } = (await res.json()) as { client_secret: string };

      const peer = new RTCPeerConnection();
      pc.current = peer;
      const audio = new Audio();
      audio.autoplay = true;
      peer.ontrack = (e) => (audio.srcObject = e.streams[0]);
      const mic = await navigator.mediaDevices.getUserMedia({
        audio: { echoCancellation: true, noiseSuppression: true, autoGainControl: true },
      });
      mic.getTracks().forEach((t) => peer.addTrack(t, mic));

      const dc = peer.createDataChannel("oai-events");
      let decided = false;
      dc.onopen = () => {
        setStatus("live");
        dc.send(JSON.stringify({ type: "response.create" })); // assistant speaks first
      };
      dc.onmessage = (ev) => {
        const msg = JSON.parse(ev.data);
        if (msg.type === "response.output_audio_transcript.done" || msg.type === "response.audio_transcript.done") {
          add({ who: "assistant", text: msg.transcript });
        } else if (msg.type === "conversation.item.input_audio_transcription.completed" && msg.transcript?.trim()) {
          add({ who: "you", text: msg.transcript });
        } else if (msg.type === "response.function_call_arguments.done" && msg.name === "record_decision") {
          const args = JSON.parse(msg.arguments || "{}");
          const action = DECISION_TO_ACTION[args.decision] ?? "edit";
          const note = [`voice: ${args.decision}`, args.note].filter(Boolean).join(" · ");
          onAction(card.id, action, note);
          add({ who: "system", text: `Decision recorded: ${args.decision}` });
          dc.send(JSON.stringify({
            type: "conversation.item.create",
            item: { type: "function_call_output", call_id: msg.call_id, output: JSON.stringify({ ok: true }) },
          }));
          dc.send(JSON.stringify({ type: "response.create" }));
          decided = true;
        } else if (msg.type === "response.done" && decided) {
          setTimeout(hangUp, 4000); // let the goodbye play out
        } else if (msg.type === "error") {
          add({ who: "system", text: `Error: ${msg.error?.message ?? "unknown"}` });
        }
      };

      const offer = await peer.createOffer();
      await peer.setLocalDescription(offer);
      const sdp = await fetch("https://api.openai.com/v1/realtime/calls", {
        method: "POST",
        body: offer.sdp,
        headers: { Authorization: `Bearer ${client_secret}`, "Content-Type": "application/sdp" },
      });
      if (!sdp.ok) throw new Error(await sdp.text());
      await peer.setRemoteDescription({ type: "answer", sdp: await sdp.text() });
    } catch (e) {
      add({ who: "system", text: `Could not start: ${(e as Error).message.slice(0, 200)}` });
      setStatus("error");
      pc.current?.close();
    }
  }

  if (autoStart && !started.current) void start();

  const live = status === "connecting" || status === "live";
  return (
    <div className="rounded-md border border-slate-200 p-3">
      <div className="flex flex-wrap items-center gap-3">
        {!live ? (
          <button className="rounded-md bg-accent px-3 py-1.5 text-sm font-medium text-white" onClick={start}>
            Talk to the assistant
          </button>
        ) : (
          <button className="rounded-md border border-danger px-3 py-1.5 text-sm font-medium text-danger" onClick={hangUp}>
            Hang up
          </button>
        )}
        <span className="text-xs text-slate-500">
          {status === "connecting" && "Connecting…"}
          {status === "live" && "Live: speak normally, decide with approve, escalate or reject"}
          {status === "ended" && "Call ended"}
          {status === "error" && "Call failed"}
        </span>
      </div>
      {lines.length > 0 && (
        <ul className="mt-3 space-y-1 text-sm">
          {lines.map((l, i) => (
            <li key={i} className={l.who === "you" ? "text-slate-500" : l.who === "system" ? "text-xs text-accent" : ""}>
              <span className="font-medium">{l.who === "assistant" ? "Assistant: " : l.who === "you" ? "You: " : ""}</span>
              {l.text}
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

"""
Optional password protection for the dashboard API when it is exposed (for example through a
tunnel to test on a phone). Active only when ASK_DASHBOARD_PASSWORD is set; any user name works.
"""

import base64
import hmac
import os

from starlette.middleware.base import BaseHTTPMiddleware
from starlette.requests import Request
from starlette.responses import Response

from ask_soony.config import load_dotenv


class BasicAuth(BaseHTTPMiddleware):
    def __init__(self, app):
        super().__init__(app)
        load_dotenv()
        self.password = os.environ.get("ASK_DASHBOARD_PASSWORD", "")

    async def dispatch(self, request: Request, call_next):
        if not self.password:
            return await call_next(request)
        header = request.headers.get("authorization", "")
        if header.startswith("Basic "):
            try:
                _, _, pw = base64.b64decode(header[6:]).decode().partition(":")
            except ValueError:
                pw = ""
            if hmac.compare_digest(pw, self.password):
                return await call_next(request)
        return Response(status_code=401, headers={"WWW-Authenticate": 'Basic realm="ask-soony"'})

